/**
 * Разметка иконки. moveat_icon( 'instagram', 'reviews-page__social-icon' ).
 * Размер задаёт font-size, цвет — color. Неизвестное имя — пустая строка.
 *
 * @param string $name    Имя иконки (ключ moveat_icons()).
 * @param string $classes Дополнительные классы.
 * @return string
 */
function moveat_icon( $name, $classes = '' ) {
	$icons = moveat_icons();
	if ( ! isset( $icons[ $name ] ) ) {
		return '';
	}

	list( $view_box, $inner ) = $icons[ $name ];
	$class = trim( 'icon icon--' . $name . ' ' . $classes );

	return sprintf(
		'<svg class="%s" viewBox="%s" aria-hidden="true" focusable="false">%s</svg>',
		esc_attr( $class ),
		esc_attr( $view_box ),
		$inner
	);
}
